module no_vowels_reconstructor (\n    input clk,\n    input rst_n,\n    input start,\n    input [127:0] message,\n    input [4:0] msg_len,\n    input [255:0] skeleton_chars,\n    input [15:0] skeleton_len,\n    input [15:0] vowel_count,\n    input [3:0] num_words,\n    output reg word_valid,\n    output reg [1:0] word_index,\n    output reg done\n);\n\n    localparam MAX_WORDS = 4;\n    localparam MAX_WORD_LEN = 8;\n    localparam MAX_MSG_LEN = 16;\n\n    // State encoding\n    localparam [3:0] IDLE            = 4'd0;\n    localparam [3:0] DP_INIT         = 4'd1;\n    localparam [3:0] DP_LOOP         = 4'd2;\n    localparam [3:0] DP_CHECK_WORD   = 4'd3;\n    localparam [3:0] DP_COMPARE_CHAR = 4'd4;\n    localparam [3:0] DP_UPDATE       = 4'd5;\n    localparam [3:0] BACKTRACK       = 4'd6;\n    localparam [3:0] OUTPUT          = 4'd7;\n    localparam [3:0] DONE_STATE      = 4'd8;\n\n    reg [3:0] state, next_state;\n\n    // Message registers\n    reg [7:0] msg_reg [0:MAX_MSG_LEN-1];\n    // Dictionary storage\n    reg [7:0] dict_skeleton [0:MAX_WORDS-1][0:MAX_WORD_LEN-1];\n    reg [3:0] dict_len [0:MAX_WORDS-1];\n    reg [3:0] dict_vcount [0:MAX_WORDS-1];\n\n    // DP tables\n    reg [7:0] dp [0:MAX_MSG_LEN];\n    reg prev [0:MAX_MSG_LEN];\n    reg [1:0] word_used [0:MAX_MSG_LEN];\n    reg reachable [0:MAX_MSG_LEN];\n\n    // Counters/indices\n    reg [4:0] i;         // Current DP position\n    reg [1:0] w;         // Current word index\n    reg [2:0] j;         // Current character in word\n    reg [4:0] pos;       // Backtrack position\n    reg [3:0] char_match_count;\n\n    // Stack for backtracking\n    reg [1:0] stack [0:MAX_MSG_LEN-1];\n    reg [4:0] stack_ptr;\n    reg [4:0] output_count;\n\n    // Control flags\n    reg word_matches;\n    reg [7:0] new_vowels;\n\n    // Temporary storage\n    reg [3:0] word_len;\n\n    integer idx, word_idx, char_idx;  // For-integer loops\n\n    // FSM and main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            word_valid <= 1'b0;\n            done <= 1'b0;\n            word_index <= 2'd0;\n            stack_ptr <= 5'd0;\n            output_count <= 5'd0;\n\n            for (idx = 0; idx < MAX_MSG_LEN; idx = idx + 1) begin\n                msg_reg[idx] <= 8'd0;\n                reachable[idx] <= 1'b0;\n                dp[idx] <= 8'd0;\n                prev[idx] <= 5'd0;\n                word_used[idx] <= 2'd0;\n                stack[idx] <= 2'd0;\n            end\n            reachable[MAX_MSG_LEN] <= 1'b0;\n            dp[MAX_MSG_LEN] <= 8'd0;\n            prev[MAX_MSG_LEN] <= 5'd0;\n            word_used[MAX_MSG_LEN] <= 2'd0;\n\n            for (word_idx = 0; word_idx < MAX_WORDS; word_idx = word_idx + 1) begin\n                dict_len[word_idx] <= 4'd0;\n                dict_vcount[word_idx] <= 4'd0;\n                for (char_idx = 0; char_idx < MAX_WORD_LEN; char_idx = char_idx + 1) begin\n                    dict_skeleton[word_idx][char_idx] <= 8'd0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    word_valid <= 1'b0;\n                    done <= 1'b0;\n                    stack_ptr <= 5'd0;\n                    output_count <= 5'd0;\n                    if (start) begin\n                        // Unpack message\n                        for (idx = 0; idx < MAX_MSG_LEN; idx = idx + 1) begin\n                            msg_reg[idx] <= (idx < msg_len) ? message[127 - 8*idx -: 8] : 8'd0;\n                        end\n\n                        // Unpack dictionary\n                        for (word_idx = 0; word_idx < MAX_WORDS; word_idx = word_idx + 1) begin\n                            if (word_idx < num_words) begin\n                                dict_len[word_idx] <= skeleton_len[4*(word_idx+1)-1 -: 4];\n                                dict_vcount[word_idx] <= vowel_count[4*(word_idx+1)-1 -: 4];\n                                for (char_idx = 0; char_idx < MAX_WORD_LEN; char_idx = char_idx + 1) begin\n                                    dict_skeleton[word_idx][char_idx] <= skeleton_chars[255 - 64*word_idx - 8*char_idx -: 8];\n                                end\n                            end else begin\n                                dict_len[word_idx] <= 4'd0;\n                                dict_vcount[word_idx] <= 4'd0;\n                                for (char_idx = 0; char_idx < MAX_WORD_LEN; char_idx = char_idx + 1) begin\n                                    dict_skeleton[word_idx][char_idx] <= 8'd0;\n                                end\n                            end\n                        end\n                        state <= DP_INIT;\n                    end\n                end\n\n                DP_INIT: begin\n                    // Initialize DP tables\n                    dp[0] <= 8'd0;\n                    reachable[0] <= 1'b1;\n                    for (idx = 1; idx <= MAX_MSG_LEN; idx = idx + 1) begin\n                        reachable[idx] <= 1'b0;\n                        dp[idx] <= 8'd0;\n                        prev[idx] <= 5'd0;\n                        word_used[idx] <= 2'd0;\n                    end\n                    i <= 5'd0;\n                    state <= DP_LOOP;\n                end\n\n                DP_LOOP: begin\n                    if (i < msg_len) begin\n                        if (reachable[i]) begin\n                            w <= 2'd0;\n                            state <= DP_CHECK_WORD;\n                        end else begin\n                            i <= i + 5'd1;\n                        end\n                    end else begin\n                        // DP complete, start backtracking\n                        state <= reachable[msg_len] ? BACKTRACK : DONE_STATE;\n                    end\n                end\n\n                DP_CHECK_WORD: begin\n                    if (w < num_words) begin\n                        word_len <= dict_len[w];\n                        if ((i + dict_len[w]) <= msg_len) begin\n                            char_match_count <= 3'd0;\n                            j <= 3'd0;\n                            state <= DP_COMPARE_CHAR;\n                        end else begin\n                            w <= w + 2'd1;\n                        end\n                    end else begin\n                        i <= i + 5'd1;\n                        state <= DP_LOOP;\n                    end\n                end\n\n                DP_COMPARE_CHAR: begin\n                    if (j < word_len) begin\n                        if (msg_reg[i + j] == dict_skeleton[w][j]) begin\n                            char_match_count <= char_match_count + 1;\n                            j <= j + 3'd1;\n                        end else begin\n                            // Mismatch found, skip this word\n                            w <= w + 2'd1;\n                            state <= DP_CHECK_WORD;\n                        end\n                    end else begin\n                        if (char_match_count == word_len) begin\n                            new_vowels <= dp[i] + dict_vcount[w];\n                            state <= DP_UPDATE;\n                        end else begin\n                            w <= w + 2'd1;\n                            state <= DP_CHECK_WORD;\n                        end\n                    end\n                end\n\n                DP_UPDATE: begin\n                    if ((!reachable[i + word_len]) || (new_vowels > dp[i + word_len])) begin\n                        dp[i + word_len] <= new_vowels;\n                        reachable[i + word_len] <= 1'b1;\n                        prev[i + word_len] <= i;\n                        word_used[i + word_len] <= w;\n                    end\n                    w <= w + 2'd1;\n                    state <= DP_CHECK_WORD;\n                end\n\n                BACKTRACK: begin\n                    pos <= msg_len;\n                    stack_ptr <= 5'd0;\n                    state <= BACKTRACK_LOOP;\n                end\n\n                BACKTRACK_LOOP: begin\n                    if (pos > 0) begin\n                        stack[stack_ptr] <= word_used[pos];\n                        stack_ptr <= stack_ptr + 5'd1;\n                        pos <= prev[pos];\n                    end else if (pos == 0) begin\n                        // Backtrack complete\n                        output_count <= stack_ptr - 5'd1;\n                        stack_ptr <= 5'd0;\n                        state <= OUTPUT;\n                    end\n                end\n\n                OUTPUT: begin\n                    if (stack_ptr <= output_count) begin\n                        word_valid <= 1'b1;\n                        word_index <= stack[output_count - stack_ptr];\n                        stack_ptr <= stack_ptr + 5'd1;\n                    end else begin\n                        word_valid <= 1'b0;\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b0;\n                    word_valid <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule